```c
#include <stdio.h>
#include <stdlib.h>

int main(void) {
    int A, B;
    if (scanf("%d %d", &A, &B) != 2) return 0;

    size_t cap = (A > 0) ? (size_t)A : 1;
    long long *SA = (long long *)malloc(cap * sizeof(long long));
    if (!SA) return 0;

    for (int i = 0; i < A; i++) {
        scanf("%lld", &SA[i]);
    }

    int pos = 0;
    int ok = 1;

    for (int j = 0; j < B; j++) {
        long long y;
        scanf("%lld", &y);

        while (pos < A && SA[pos] != y) {
            pos++;
        }

        if (pos == A) {
            ok = 0;
            break;
        }
        pos++;
    }

    printf("%c\n", ok ? 'S' : 'N');

    free(SA);
    return 0;
}
```

